//   new  src/components/FollowList.js                    the list (both modes)
//   new  src/app/followers/page.js                       your followers
//   new  src/app/following/page.js                       who you follow
//   new  src/app/profile/[username]/followers/page.js    someone else's
//   new  src/app/profile/[username]/following/page.js
//   edit src/lib/profileSettingsApi.js                   + getFollowers,
//                                                        getFollowing
//   edit src/app/profile/[username]/page.js              counts become links
//   edit src/app/profile/page.js                         count reads
//                                                        followerCount (was
//                                                        followersCount, so it
//                                                        showed 0) + listens to
//                                                        "profile:followers"
//   edit src/content/locales/*.json                      app.profile.noFollowers
//                                                        / noFollowing, 12
//                                                        languages
//
//   node apply-follow-web.cjs            run from the project root
//   node apply-follow-web.cjs --dry-run  show what would change
//   node apply-follow-web.cjs --force    also overwrite files you have edited
//
// Every file it touches is backed up to .follow-backup/<timestamp>/ first.
// Safe to run twice: already-updated files are skipped.
